async function createServer() {
  const server = new McpServer(
    { name: 'test-server', version: '1.0.0', description: 'Test server for outcome unwrap' },
    { adapter: new ValibotJsonSchemaAdapter(), capabilities: { tools: { listChanged: true } } }
  ).withContext<StorybookContext>();

  await server.receive(
    {
      jsonrpc: '2.0',
      id: 1,
      method: 'initialize',
      params: {
        protocolVersion: '2025-06-18',
        capabilities: {},
        clientInfo: { name: 'test', version: '1.0.0' },
      },
    },
    { sessionId: 'test-session' }
  );

  return server;
}

function createManifestProvider() {
  return vi.fn(async (_request: Request | undefined, path: string) => {
    if (path !== COMPONENT_MANIFEST_PATH) {
      throw new ManifestGetError('Failed to fetch manifest: 404 Not Found', path);
    }
    return JSON.stringify(smallManifestFixture);
  });
}

async function callListTool(server: McpServer<any, StorybookContext>) {
  const response = await server.receive(
    {
      jsonrpc: '2.0' as const,
      id: 2,
      method: 'tools/call',
      params: { name: LIST_TOOL_NAME, arguments: {} },
    },
    {
      custom: {
        request: new Request('https://example.com/mcp'),
        manifestProvider: createManifestProvider(),
      },
    }
  );
  return (response as { result: { content: Array<{ text: string }>; isError?: boolean } }).result;
}

describe('hosted outcome unwrap', () => {
  // The global setup turns console.error into a test failure; this file asserts on it instead.
  let consoleError: ReturnType<typeof vi.spyOn>;

  beforeEach(() => {
    listMethod.output = undefined;
    listMethod.handler = undefined;
    consoleError = vi.spyOn(console, 'error').mockImplementation(() => {});
  });

  it('publishes a method output schema as MCP tool metadata', async () => {
    listMethod.output = v.object({ manifests: v.looseObject({}) });
    const server = await createServer();
    await addListAllDocumentationTool(server);

    const response = await server.receive(
      { jsonrpc: '2.0', id: 3, method: 'tools/list', params: {} },
      { sessionId: 'test-session' }
    );
    const [tool] = (response as { result: { tools: Array<Record<string, unknown>> } }).result.tools;

    expect(tool.name).toBe(LIST_TOOL_NAME);
    expect(tool.outputSchema).toMatchObject({
      type: 'object',
      properties: { manifests: expect.anything() },
    });
  });

  it('emits structuredContent narrowed to the published output schema', async () => {
    // A strict subset of the real outcome data: validation must strip everything undeclared.
    listMethod.output = v.object({ manifests: v.looseObject({}) });
    const server = await createServer();
    await addListAllDocumentationTool(server);

    const result = (await callListTool(server)) as { structuredContent?: Record<string, unknown> };

    expect(result.structuredContent).toBeDefined();
    expect(Object.keys(result.structuredContent!)).toEqual(['manifests']);
    expect(consoleError).not.toHaveBeenCalled();
  });

  it('maps a failure outcome to isError and still emits its validated structuredContent', async () => {
    listMethod.output = v.object({ reason: v.string() });
    listMethod.handler = () => ({
      ok: false,
      data: { reason: 'nothing indexed', internal: 'not-published' },
      markdown: 'Nothing indexed yet.',
    });
    const server = await createServer();
    await addListAllDocumentationTool(server);

    const result = (await callListTool(server)) as {
      content: Array<{ type: string; text: string }>;
      structuredContent?: Record<string, unknown>;
      isError?: boolean;
    };

    expect(result.isError).toBe(true);
    expect(result.content).toEqual([{ type: 'text', text: 'Nothing indexed yet.' }]);
    expect(result.structuredContent).toEqual({ reason: 'nothing indexed' });
    expect(consoleError).not.toHaveBeenCalled();
  });

  it('reports and logs outcome data its published output schema rejects', async () => {
    listMethod.output = v.object({ fieldTheDataDoesNotHave: v.string() });
    const server = await createServer();
    await addListAllDocumentationTool(server);

    const result = await callListTool(server);

    expect(result.isError).toBe(true);
    expect(result.content[0].text).toContain('did not match its published output schema');
    expect(consoleError).toHaveBeenCalledTimes(1);
  });

  it('surfaces agent-facing errors verbatim, without the generic error prefix', async () => {
    // The trait is a property read, never a class list — it must travel across bundle copies.
    listMethod.handler = () => {
      throw Object.assign(new Error('Do X, then retry the tool.'), { agentFacing: true });
    };
    const server = await createServer();
    await addListAllDocumentationTool(server);

    const result = await callListTool(server);

    expect(result.isError).toBe(true);
    expect(result.content[0].text).toBe('Do X, then retry the tool.');
    expect(consoleError).not.toHaveBeenCalled();
  });

  it('logs unexpected failures so they reach the server terminal, not only the transcript', async () => {
    listMethod.handler = () => {
      throw new Error('boom');
    };
    const server = await createServer();
    await addListAllDocumentationTool(server);

    const result = await callListTool(server);

    expect(result.isError).toBe(true);
    expect(result.content[0].text).toBe('Unexpected error: boom');
    expect(consoleError).toHaveBeenCalledTimes(1);
  });
});

/**
 * Registers the docs tools of a hosted Storybook from the shared core toolset.
 *
 * Everything an MCP client observes — the frozen tool names, the descriptions, the schemas and the
 * rendered text — comes from the toolset. This module contributes only what is specific to serving
 * a hosted Storybook: building the per-request access over the manifest provider, composing one
 * access per source, and the telemetry callbacks this package's embedders rely on.
 */

import type { McpServer } from 'tmcp';
import type { GenericSchema } from 'valibot';

import {
  createCompositionDocsSources,
  createDocsToolset,
  createProviderDocsAccess,
  emptyManifests,
  selectReportedManifests,
  ManifestGetError,
  RequiresOwnMcpError,
  resolveToolsetDescription,
  toMcpToolName,
  type DocsListOutput,
  type DocsSource,
  type DocsToolset,
  type ToolsetCtx,
  type ToolsetOutcome,
} from 'storybook/internal/toolsets-docs';

import type { StorybookContext } from '../types.ts';
import { errorToMCPContent } from '../utils/error-to-mcp-content.ts';
import { toSourceManifests } from '../utils/multi-source-manifests.ts';

export const LIST_TOOL_NAME = toMcpToolName('docs.list');
export const GET_TOOL_NAME = toMcpToolName('docs.show');
export const GET_STORY_TOOL_NAME = toMcpToolName('docs.showStory');

type Server = McpServer<any, StorybookContext>;
type ToolEnabled = Parameters<Server['tool']>[0]['enabled'];

const ctx: ToolsetCtx = {
  transport: 'mcp',
  getService: () => {
    throw new Error('Open services are not available in a hosted Storybook.');
  },
};

/**
 * The composed sources this request serves, or nothing when this Storybook stands alone.
 *
 * Only the "is this a composition" test is hosted-specific — a configured source without a URL is
 * this Storybook itself. Building the accesses is the shared helper's job, so hosted and dev-server
 * compositions cannot drift apart.
 */
function getSources(context: StorybookContext | undefined): DocsSource[] | undefined {
  const sources = context?.sources;
  if (!sources?.some((source) => source.url)) {
    return undefined;
  }

  return createCompositionDocsSources({
    sources,
    manifestProvider: context?.manifestProvider,
    getRequest: () => context?.request,
    resolveEntry: context?.resolveEntry,
  });
}

/**
 * Builds the toolset for one request.
 *
 * The manifests, the provider and the composed sources all belong to the request being served, so
 * the toolset is assembled per call. It is a plain object of schemas and functions, which is why
 * that is cheap enough to do rather than threading request state through a shared instance.
 */
function toolsetFor(context: StorybookContext | undefined): DocsToolset {
  const sources = getSources(context);
  if (sources) {
    return createDocsToolset({ sources });
  }

  return createDocsToolset({
    docsAccess: createProviderDocsAccess({
      manifestProvider: context?.manifestProvider,
      getRequest: () => context?.request,
      resolveEntry: context?.resolveEntry,
    }),
  });
}

/**
 * Metadata is read from a toolset with no access behind it: names, titles, descriptions and schemas
 * are static, and only `multiSource` changes them.
 */
function metadataToolset(multiSource: boolean): DocsToolset {
  const unavailable = { list: async () => emptyManifests(), resolve: async () => undefined };
  return multiSource
    ? createDocsToolset({
        sources: [{ source: { id: 'local', title: 'Local' }, access: unavailable }],
      })
    : createDocsToolset({ docsAccess: unavailable });
}

/**
 * What an embedder needs to register one of these tools on its own server.
 *
 * The type is written out rather than inferred: the schemas come from the bundled core toolset, so
 * an inferred signature would name valibot types this package's `.d.ts` cannot reference.
 */
export type DocsToolMetadata = {
  name: string;
  title: string;
  description: string;
  schema: GenericSchema;
  outputSchema?: GenericSchema;
};

function toolMetadata(
  method: 'docs.list' | 'docs.show' | 'docs.showStory',
  multiSource: boolean
): DocsToolMetadata {
  const [, methodName] = method.split('.') as [string, 'list' | 'show' | 'showStory'];
  const definition = metadataToolset(multiSource).methods[methodName];
  const outputSchema = outputSchemaOf(definition);

  return {
    name: toMcpToolName(method),
    title: definition.title,
    description: resolveToolsetDescription(definition.description, ctx),
    schema: definition.input,
    ...(outputSchema ? { outputSchema } : {}),
  };
}

export function getListAllDocumentationToolMetadata(options?: {
  multiSource?: boolean;
}): DocsToolMetadata {
  return toolMetadata('docs.list', !!options?.multiSource);
}

export function getDocumentationToolMetadata(options?: {
  multiSource?: boolean;
}): DocsToolMetadata {
  return toolMetadata('docs.show', !!options?.multiSource);
}

export function getStoryDocumentationToolMetadata(options?: {
  multiSource?: boolean;
}): DocsToolMetadata {
  return toolMetadata('docs.showStory', !!options?.multiSource);
}

/**
 * The one place this package crosses the tmcp type-inference boundary: tmcp types a tool's metadata
 * and handler from a literal schema generic, but these schemas come from the bundled core toolset
 * and resolve only at runtime, so registration steps out of that inference here.
 */
function registerTool(
  server: Server,
  metadata: DocsToolMetadata & { enabled?: ToolEnabled },
  handler: (input: never) => Promise<unknown>
): void {
  server.tool(metadata as never, handler as never);
}

/**
 * No docs method declares an output schema today, so the literal-inferred method types omit the
 * property; reading it structurally lets a method that gains one publish it without edits here.
 */
function outputSchemaOf(definition: unknown): GenericSchema | undefined {
  return (definition as { output?: GenericSchema }).output;
}

/**
 * Whether an error's prose speaks to the agent and names its own recovery.
 *
 * The trait is a property read, not a class list: it travels with the instance even across bundle
 * copies.
 */
function isAgentFacingError(error: unknown): error is Error {
  return error instanceof Error && (error as { agentFacing?: boolean }).agentFacing === true;
}

/**
 * Narrows outcome data to the published output contract.
 *
 * Outcomes may carry more data than the contract declares (the rendered Markdown needs it); only
 * the declared shape reaches `structuredContent`. A mismatch is a maintainer bug, thrown as a
 * plain error — core's typed class lives outside this package's dependency-light closure — and
 * lands in the generic catch below, which logs it and reports it as an unexpected failure.
 */
async function toStructuredContent(
  outputSchema: GenericSchema | undefined,
  data: unknown
): Promise<Record<string, unknown> | undefined> {
  if (!outputSchema || data === undefined) {
    return undefined;
  }
  const result = await outputSchema['~standard'].validate(data);
  if (result.issues) {
    // Validation issues embed the rejected input, which can be large or circular — the diagnostic
    // must never throw or balloon while reporting the real bug.
    let serialized: string;
    try {
      serialized = JSON.stringify(result.issues)?.slice(0, 2000) ?? String(result.issues);
    } catch {
      serialized = `${result.issues.length} issue(s) that could not be serialized`;
    }
    throw new Error(`Toolset output did not match its published output schema: ${serialized}`);
  }
  return result.value as Record<string, unknown>;
}

/**
 * Runs one method against the request's toolset and unwraps its outcome into an MCP result.
 *
 * A manifest that cannot be fetched or parsed is reported as tool output rather than thrown, so the
 * agent reads why instead of receiving a transport error. `data` is undefined in that case, which
 * is how the callers know to skip their telemetry hooks.
 */
async function call<TMethod extends 'list' | 'show' | 'showStory'>(
  server: Server,
  method: TMethod,
  input: unknown
) {
  const context = server.ctx.custom;

  try {
    const definition = toolsetFor(context).methods[method];
    const outcome = await (
      definition.handler as (i: unknown, c: ToolsetCtx) => Promise<ToolsetOutcome<unknown>>
    )(input, ctx);
    const structuredContent = await toStructuredContent(outputSchemaOf(definition), outcome.data);
    const blocks = Array.isArray(outcome.markdown) ? outcome.markdown : [outcome.markdown];

    return {
      data: outcome.data,
      result: {
        content: blocks.map((text) => ({ type: 'text' as const, text })),
        ...(structuredContent !== undefined ? { structuredContent } : {}),
        ...(outcome.ok ? {} : { isError: true as const }),
      },
    };
  } catch (error) {
    // An agent-facing error is surfaced as-is instead of being wrapped as an unexpected failure.
    if (isAgentFacingError(error)) {
      return {
        data: undefined,
        result: {
          content: [{ type: 'text' as const, text: error.message }],
          isError: true as const,
        },
      };
    }
    // Everything except the two designed answers (a source that needs its own MCP, an unreadable
    // manifest) is a bug whose only other evidence would be some agent's transcript. `console`
    // rather than a logger, because this package stays dependency-light and runtime-agnostic.
    if (!(error instanceof RequiresOwnMcpError) && !(error instanceof ManifestGetError)) {
      console.error(error);
    }
    return { data: undefined, result: errorToMCPContent(error) };
  }
}

export async function addListAllDocumentationTool(
  server: Server,
  enabled?: ToolEnabled,
  options?: { multiSource?: boolean }
) {
  registerTool(
    server,
    { ...getListAllDocumentationToolMetadata(options), enabled },
    async (input: unknown) => {
      const context = server.ctx.custom;
      const { data, result } = await call(server, 'list', input);

      // The embedder's hook predates the toolset and reports one source's manifests, so it picks
      // the same source the toolset's own usage event does.
      const listing = data as DocsListOutput | undefined;
      const manifests = listing && selectReportedManifests(listing);
      if (manifests) {
        await context?.onListAllDocumentation?.({
          context: context!,
          manifests,
          resultText: result.content[0].text,
          ...(listing?.sources ? { sources: listing.sources.map(toSourceManifests) } : {}),
        });
      }

      return result;
    }
  );
}

export async function addGetDocumentationTool(
  server: Server,
  enabled?: ToolEnabled,
  options?: { multiSource?: boolean }
) {
  registerTool(
    server,
    { ...getDocumentationToolMetadata(options), enabled },
    async (input: { id: string; storybookId?: string }) => {
      const context = server.ctx.custom;
      const { data, result } = await call(server, 'show', input);

      // Skipped when the manifest itself could not be read: that is a transport failure, not a
      // lookup with an outcome to report.
      if (data) {
        const { entry } = data as {
          entry?: { kind: string; component?: unknown; doc?: unknown };
        };
        const found = entry
          ? entry.kind === 'component'
            ? entry.component
            : entry.doc
          : undefined;

        await context?.onGetDocumentation?.(
          found
            ? {
                context: context!,
                input,
                foundDocumentation: found as never,
                resultText: result.content[0].text,
              }
            : { context: context!, input }
        );
      }

      return result;
    }
  );
}

export async function addGetStoryDocumentationTool(
  server: Server,
  enabled?: ToolEnabled,
  options?: { multiSource?: boolean }
) {
  registerTool(
    server,
    { ...getStoryDocumentationToolMetadata(options), enabled },
    async (input: unknown) => (await call(server, 'showStory', input)).result
  );
}

import type { ComponentDoc } from 'react-docgen-typescript';
import type {
  AllManifests,
  ComponentManifest,
  ComponentManifestMap,
  Doc,
  DocsManifestMap,
  Story,
} from 'storybook/internal/toolsets-docs';
import * as v from 'valibot';

/**
 * Represents a single Storybook source (local or remote).
 */
export type Source = {
  /** Unique identifier for this source (e.g., 'local', 'tetra') */
  id: string;
  /** Human-readable title (e.g., 'Local', 'Tetra Design System') */
  title: string;
  /** Remote URL, undefined for local source */
  url?: string;
};

export type RequiresOwnMcpNotice = {
  kind: 'requires-own-mcp';
  endpoint: string;
};

/**
 * All manifests for a single source.
 */
export type SourceManifests = {
  source: Source;
  componentManifest: ComponentManifestMap;
  docsManifest?: DocsManifestMap;
  /** Error message if fetching this source failed */
  error?: string;
  /** Non-error guidance for sources that must be accessed through their own MCP endpoint */
  notice?: RequiresOwnMcpNotice;
};

/**
 * Custom context passed to MCP server and tools.
 * Contains the request object and optional manifest provider.
 */
export type StorybookContext = {
  /**
   * The incoming HTTP request being processed.
   */
  request?: Request;
  /**
   * Optional function to provide custom manifest retrieval logic.
   * If provided, this function will be called instead of the default fetch-based provider.
   * The function receives the request object, a path to the manifest file, and optionally
   * a source (in multi-source mode).
   * The default provider requires a request object and constructs the manifest URL from the request origin,
   * using the top-level manifest path such as /manifests/components.json.
   * Custom providers can use the request parameter to determine the manifest source, or ignore it entirely.
   */
  manifestProvider?: (
    request: Request | undefined,
    path: string,
    source?: Source
  ) => Promise<string>;
  /**
   * Sources configuration for multi-source mode.
   * When provided, tools will fetch and display manifests grouped by source.
   */
  sources?: Source[];
  /**
   * Optional handler called when the docs-list tool is invoked.
   * Receives the context and the component manifest.
   */
  onListAllDocumentation?: (params: {
    context: StorybookContext;
    manifests: AllManifests;
    resultText: string;
    /** Present in multi-source mode — all source manifests including errors */
    sources?: SourceManifests[];
  }) => void | Promise<void>;
  /**
   * Optional handler called when the docs-show tool is invoked.
   * Receives the context, input parameters, and the found component (if any).
   */
  onGetDocumentation?: (
    params: {
      context: StorybookContext;
      input: { id: string; storybookId?: string };
    } & (
      | { foundDocumentation: ComponentManifest | Doc; resultText: string }
      | { foundDocumentation?: never; resultText?: never }
    )
  ) => void | Promise<void>;
  /**
   * Optional in-process resolver for a single component or docs entry, used in
   * Storybook's dev server when `experimentalDocgenServer` is enabled. When set,
   * single-entry tools (`docs-show`, `docs-show-story`) call
   * this instead of fetching the (potentially all-component) manifest index, so a
   * single lookup never triggers docgen extraction for every component.
   *
   * Returns the fully-resolved component or doc in `@storybook/mcp`'s internal
   * shape (already adapted from the open-service payloads), or `undefined` when the
   * id is unknown.
   */
  resolveEntry?: (id: string, source?: Source) => Promise<ResolvedEntry | undefined>;
};

/**
 * Result of resolving a single id via {@link StorybookContext.resolveEntry}: either a
 * fully-resolved component manifest or a standalone docs entry.
 */
export type ResolvedEntry =
  | { kind: 'component'; component: ComponentManifest }
  | { kind: 'doc'; doc: Doc };

/**
 * The manifest schemas come from Storybook's shared docs toolset, which this package bundles, so a
 * hosted Storybook and a dev server validate the same wire format rather than two copies of it.
 * They are re-exported here because embedders import them from this package's root.
 */
export {
  ComponentManifestMap,
  ComponentManifestMapV0,
  ComponentManifestMapV1,
  DocsManifestMap,
  DocsManifestMapV0,
  DocsManifestMapV1,
  JsonRef,
} from 'storybook/internal/toolsets-docs';
export type {
  AllManifests,
  ComponentManifest,
  ComponentManifestEntry,
  ComponentManifestV0,
  ComponentManifestV1,
  Doc,
  DocEntry,
  DocV0,
  DocV1,
  Story,
  SubcomponentManifest,
} from 'storybook/internal/toolsets-docs';

/** Component documentation from react-docgen-typescript, extended with export name. */
export type ComponentDocWithExportName = ComponentDoc & { exportName: string };

/**
 * Open-service payload contracts (the "core format") that Storybook's
 * `experimentalDocgenServer` mode produces. `@storybook/mcp` adapts these into its
 * internal {@link ComponentManifest}/{@link Doc} shapes in one place
 * (`adaptCoreComponent`/`adaptCoreDoc`). Defined structurally (not as schemas) so
 * the addon can build them in-process without importing Storybook core.
 */

/** One story snippet from the `core/story-docs` service. */
export type CoreStoryDoc = {
  id: string;
  name: string;
  snippet?: string;
  description?: string;
  summary?: string;
  error?: { name: string; message: string };
};

/** One MDX doc from the `addon-docs/mdx` service. */
export type CoreMdxDoc = {
  id: string;
  name: string;
  path?: string;
  title?: string;
  content?: string;
  summary?: string;
  error?: { name: string; message: string };
};

/**
 * Payload returned by the `addon-docs/mdx` service for a component or standalone
 * docs entry.
 */
export type CoreMdxPayload = {
  id: string;
  name: string;
  docs: Record<string, CoreMdxDoc>;
};

/** Payload returned by the `core/story-docs` service for one component. */
export type CoreStoryDocsPayload = {
  id: string;
  name: string;
  path: string;
  import?: string;
  stories: Record<string, CoreStoryDoc>;
  error?: { name: string; message: string };
};

/**
 * Payload returned by the `core/docgen` service for one component. `argTypes` (a
 * UI-normalized view) is intentionally ignored by the adapter; prop types come
 * from `reactComponentMeta`/`react*` fields.
 */
export type CoreDocgenPayload = {
  id: string;
  name: string;
  path?: string;
  description?: string;
  summary?: string;
  jsDocTags?: Record<string, string[]>;
  import?: string;
  reactComponentMeta?: unknown;
  reactDocgen?: unknown;
  reactDocgenTypescript?: unknown;
  subcomponents?: Record<string, unknown>;
  error?: { name: string; message: string };
  [key: string]: unknown;
};

/**
 * A component assembled from the `core/docgen` payload plus the `core/story-docs`
 * stories and resolved attached MDX docs.
 */
export type CoreDocgenComponent = CoreDocgenPayload & {
  import?: string;
  /** Story snippets, either as a story-docs record or an already-resolved array. */
  stories?: Record<string, CoreStoryDoc> | Story[];
  /** Attached docs keyed by doc id (resolved MDX payloads). */
  docs?: Record<string, CoreMdxDoc>;
};

/**
 * Shared Valibot field for the storybookId input, used in multi-source mode.
 * Reused across tools that support source selection.
 */
export const StorybookIdField = {
  storybookId: v.pipe(
    v.string(),
    v.description(
      'The Storybook source ID (e.g., "local", "tetra"). Required when multiple Storybooks are composed. See docs-list for available sources.'
    )
  ),
};

import { describe, it, expect } from 'vitest';
import { ManifestGetError } from 'storybook/internal/toolsets-docs';

import { errorToMCPContent } from './error-to-mcp-content.ts';

describe('errorToMCPContent', () => {
  it('should convert ManifestGetError to MCP error content', () => {
    const error = new ManifestGetError('Failed to get', 'https://example.com');

    const result = errorToMCPContent(error);

    expect(result).toEqual({
      content: [
        {
          type: 'text',
          text: 'Error getting manifest: Failed to get',
        },
      ],
      isError: true,
    });
  });

  it('should convert generic Error to MCP error content', () => {
    const error = new Error('Something went wrong');

    const result = errorToMCPContent(error);

    expect(result).toEqual({
      content: [
        {
          type: 'text',
          text: 'Unexpected error: Something went wrong',
        },
      ],
      isError: true,
    });
  });

  it('should handle ManifestGetError with cause', () => {
    const cause = new Error('Network error');
    const error = new ManifestGetError('Failed to get manifest', 'https://example.com', cause);

    const result = errorToMCPContent(error);

    expect(result).toEqual({
      content: [
        {
          type: 'text',
          text: 'Error getting manifest: Failed to get manifest\nCaused by: Network error',
        },
      ],
      isError: true,
    });
  });

  it('should handle ManifestGetError without URL', () => {
    const error = new ManifestGetError('Failed to get');

    const result = errorToMCPContent(error);

    expect(result).toEqual({
      content: [
        {
          type: 'text',
          text: 'Error getting manifest: Failed to get',
        },
      ],
      isError: true,
    });
  });
});

import {
  formatRequiresOwnMcpNotice,
  ManifestGetError,
  RequiresOwnMcpError,
} from 'storybook/internal/toolsets-docs';

type MCPTextResult = {
  content: Array<{ type: 'text'; text: string }>;
  isError?: true;
};

/**
 * Converts a thrown error into an MCP result.
 *
 * A source that requires its own endpoint is not a failure — it is an answer telling the agent
 * where to go — so it is returned without the error flag.
 */
export const errorToMCPContent = (error: unknown): MCPTextResult => {
  if (error instanceof RequiresOwnMcpError) {
    return {
      content: [{ type: 'text', text: formatRequiresOwnMcpNotice(error.source, error.endpoint) }],
    };
  }

  const errorPrefix =
    error instanceof ManifestGetError ? 'Error getting manifest' : 'Unexpected error';
  const errorMessage = error instanceof Error ? error.message : String(error);

  let fullMessage = `${errorPrefix}: ${errorMessage}`;
  if (error instanceof ManifestGetError && error.cause) {
    const causeMessage = error.cause instanceof Error ? error.cause.message : String(error.cause);
    fullMessage += `\nCaused by: ${causeMessage}`;
  }

  return {
    content: [{ type: 'text', text: fullMessage }],
    isError: true,
  };
};

/**
 * The package's published multi-source manifest API.
 *
 * The docs tools no longer go through this — they read composed sources through the shared toolset
 * — but embedders import it directly, so it stays part of the public surface with its original
 * signature and flat result shape.
 */

import {
  createCompositionDocsSources,
  listSources,
  type ManifestProvider,
  type Source,
  type SourceListing,
} from 'storybook/internal/toolsets-docs';

import type { SourceManifests } from '../types.ts';

/**
 * Flattens a source listing into this package's published shape.
 *
 * The toolset nests a source's manifests under `manifests`; every consumer of this package reads
 * `componentManifest` and `docsManifest` directly off the source, and that is contractual.
 */
export function toSourceManifests(listing: SourceListing): SourceManifests {
  const { source, manifests, error, notice } = listing;
  return {
    source,
    componentManifest: manifests?.componentManifest ?? { v: 1 as const, components: {} },
    ...(manifests?.docsManifest ? { docsManifest: manifests.docsManifest } : {}),
    ...(error ? { error } : {}),
    ...(notice ? { notice } : {}),
  };
}

/**
 * Fetches every source's manifests, capturing a failure as that source's own outcome rather than
 * losing the whole listing. Throws only when no source produced anything usable.
 */
export async function getMultiSourceManifests(
  sources: Source[],
  request?: Request,
  manifestProvider?: ManifestProvider
): Promise<SourceManifests[]> {
  const listings = await listSources(
    createCompositionDocsSources({ sources, manifestProvider, getRequest: () => request }),
    { withStoryIds: false }
  );

  return listings.map(toSourceManifests);
}

